#!/bin/bash
SANDBOX="$1"

cat > "$SANDBOX/vars.env" <<'ENV'
APP_NAME=linuxmissions
APP_PORT=9090
APP_ENV=production
ENV

# What app.conf must look like for the values above.
cat > "$SANDBOX/app.conf.example" <<'CONF'
# app.conf - generated by generate.sh, do not edit by hand
[app]
name = linuxmissions
environment = production
listen = 0.0.0.0:9090
url = http://localhost:9090/

[logging]
format = $remote_addr "$request" $status
CONF

cat > "$SANDBOX/generate.sh" <<'SCRIPT'
#!/bin/bash
# generate.sh - build app.conf from the values in vars.env
# TODO: load vars.env, then write app.conf with a heredoc
SCRIPT

chmod +x "$SANDBOX/generate.sh"
